        try (Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(sql)) {
            rs.next();
            if (rs.getInt(1) > 0) {
                return;
            }
        }

        Room[] rooms = new Room[]{
            new Room(101, RoomType.STANDARD, 2, new BigDecimal("249.90")),
