        Connection conn = Database.getConnection();

        String sql = "SELECT number, type, capacity, nightly_rate FROM rooms WHERE number = ?";
        try (PreparedStatement pstmt = conn.prepareStatement(sql)) {
            pstmt.setInt(1, number);
