            for (Reservation r : reservations) {
                roomReservationMap.put(r.getRoomNumber(), r);
            }

            List<Room> allRooms = roomRepo.findAll();
            for (Room room : allRooms) {
                if (roomReservationMap.containsKey(room.getNumber())) {
